-- Transaction-only: exercise private authoring, publication, dashboard isolation and client contributions.
begin;
do $$
declare owner_claims text; buyer_claims text; buyer uuid; w jsonb; c jsonb; contact jsonb; external_client jsonb; principal_contact jsonb;
 mandate uuid; source_room uuid; shared uuid; grant_data jsonb; file jsonb; blocked boolean; item jsonb; priv_path text;
begin
 select jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal2')::text into owner_claims from auth.users u join auth.sessions s on s.user_id=u.id where u.email='owner@example.invalid' limit 1;
 select u.id,jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal1')::text into buyer,buyer_claims from auth.users u join auth.sessions s on s.user_id=u.id where u.email='buyer@example.invalid' limit 1;
 update public.ig_profiles set policy_version=ig_private.current_policy() where id=buyer;
 insert into public.ig_consents(user_id,purpose,granted,version,policy_hash) select buyer,'registration',true,version,sha256 from public.ig_policy_releases where current;
 perform set_config('request.jwt.claims',owner_claims,true);
 c=public.ig_client_manage('{"action":"client_save","name":"Fixture promoter","practice":"retail-leasing","stage":"engaged"}');
 external_client=public.ig_client_manage('{"action":"client_save","name":"Fixture brand","practice":"retail-leasing","stage":"engaged"}');
 principal_contact=public.ig_client_manage(jsonb_build_object('action','contact_save','client_id',c->'id','name','Promoter staff','email','promoter@example.invalid','portal_enabled',true));
 contact=public.ig_client_manage(jsonb_build_object('action','contact_save','client_id',external_client->'id','name','Brand','email','buyer@example.invalid','portal_enabled',true));
 w=public.ig_content_intake(jsonb_build_object('action','begin','kind','retail_space','practice','retail-leasing','request_id',gen_random_uuid()));
 mandate=(w->>'content_id')::uuid;source_room=(w->>'room_id')::uuid;
 priv_path=mandate::text||'/'||gen_random_uuid()||'.pdf';
 insert into storage.objects(bucket_id,name) values('ig-retail-plans',priv_path);
 item=public.ig_save_content(jsonb_build_object('id',mandate,'version',w->'version','kind','retail_space','practice','retail-leasing','title','Fixture mall','slug','fixture-retail-mall','body','Ground floor promenade.','summary','A retail mandate.',
 'public_data',jsonb_build_object('formats','Mall','plans',jsonb_build_array(jsonb_build_object('path',priv_path,'type','Floor drawing','label','Ground floor')),'units','[{"unit":"G01","floor":"Ground","area":"1200 sq ft","basis":"Carpet","zone":"Fashion","status":"Available"}]'::jsonb)));
 blocked=false;begin perform public.ig_content_action(jsonb_build_object('action','publish','id',mandate,'version',item->'version','factsConfirmed',true,'privacyConfirmed',true,'rightsConfirmed',true));exception when others then blocked=true;end;assert blocked,'Unassigned client mandate went live';
 shared=(public.ig_retail_manage(jsonb_build_object('action','assign','content_id',mandate,'client_id',c->'id','title','Private mall mandate','confirmed',true,'terms','Signed fixture agreement','contact_ids',jsonb_build_array(principal_contact->'id')))->>'room_id')::uuid;
 assert shared<>source_room;
 perform public.ig_content_action(jsonb_build_object('action','publish','id',mandate,'version',item->'version','factsConfirmed',true,'privacyConfirmed',true,'rightsConfirmed',true));
 assert exists(select from public.ig_public_content where id=mandate and public_data->'units'->0->>'unit'='G01' and public_data->'plans'->0->>'path'=priv_path);
 grant_data=jsonb_build_object('action','contact','content_id',mandate,'contact_id',contact->'id','side','Brand','mode','dashboard','expires_at',now()+interval '20 days');
 perform public.ig_retail_manage(grant_data);
 perform set_config('request.jwt.claims',buyer_claims,true);
 assert exists(select from public.ig_retail_dashboard() where room_id=shared and not room_open);
 assert not ig_private.room_access(shared) and not ig_private.room_access(source_room);
 perform set_config('request.jwt.claims',owner_claims,true);perform public.ig_retail_manage(grant_data||'{"mode":"upload"}');
 perform set_config('request.jwt.claims',buyer_claims,true);
 assert public.ig_retail_can_upload(shared) and ig_private.room_access(shared) and not ig_private.room_access(source_room);
 assert jsonb_array_length(public.ig_room_dashboard(jsonb_build_object('id',shared)))=1;
 file=public.ig_room_manage(jsonb_build_object('action','upload_prepare','room_id',shared,'name','layout.pdf','mime','application/pdf','bytes',275,'download_enabled',true));
 assert file->>'folder'='Client uploads' and not (file->>'download_enabled')::boolean and file->>'status'='pending';
 assert public.ig_room_authorize(jsonb_build_object('action','upload','id',file->'id'))->>'id'=file->>'id';
 blocked=false;begin perform public.ig_room_manage(jsonb_build_object('action','upload_complete','id',file->'id','version',file->'version','broker_secret','incorrect'));exception when insufficient_privilege then blocked=true;end;assert blocked;
 insert into ig_private.room_config(id,broker_secret_hash) values(true,encode(extensions.digest(convert_to(repeat('f',48),'UTF8'),'sha256'),'hex')) on conflict(id) do update set broker_secret_hash=excluded.broker_secret_hash;
 perform public.ig_room_manage(jsonb_build_object('action','upload_complete','id',file->'id','version',file->'version','broker_secret',repeat('f',48)));
 assert exists(select from public.ig_room_files where id=(file->>'id')::uuid and status='ready');
 file=public.ig_room_manage(jsonb_build_object('action','upload_prepare','room_id',shared,'name','second.pdf','mime','application/pdf','bytes',275));
 perform set_config('request.jwt.claims',owner_claims,true);perform public.ig_retail_manage(grant_data||'{"mode":"view"}');
 perform set_config('request.jwt.claims',buyer_claims,true);
 assert not public.ig_retail_can_upload(shared) and ig_private.room_access(shared);
 blocked=false;begin perform public.ig_room_authorize(jsonb_build_object('action','upload','id',file->'id'));exception when insufficient_privilege then blocked=true;end;assert blocked,'Revoked contributor completed upload';
 perform set_config('request.jwt.claims',owner_claims,true);perform public.ig_retail_manage(grant_data||'{"mode":"off"}');
 w=public.ig_content_intake(jsonb_build_object('action','begin','kind','retail_requirement','practice','retail-leasing','request_id',gen_random_uuid()));
 item=public.ig_save_content(jsonb_build_object('id',w->'content_id','version',w->'version','kind','retail_requirement','practice','retail-leasing','title','Brand expansion','slug','fixture-brand-expansion','body','Compact stores.','summary','Brand brief','public_data','{"formats":"Inline","markets":"Pune","floors":"Ground","area_range":"1000–1500 sq ft"}'::jsonb));
 perform public.ig_retail_manage(jsonb_build_object('action','assign','content_id',w->'content_id','client_id',external_client->'id','title','Brand expansion','confirmed',true,'terms','Executed brand mandate','contact_ids',jsonb_build_array(contact->'id')));
 perform public.ig_content_action(jsonb_build_object('action','publish','id',item->'id','version',item->'version','factsConfirmed',true,'privacyConfirmed',true,'rightsConfirmed',true));
 assert exists(select from public.ig_public_content where kind='retail_requirement' and public_data->>'floors'='Ground');
 w=public.ig_content_intake(jsonb_build_object('action','begin','kind','retail_requirement','practice','retail-leasing','request_id',gen_random_uuid()));
 perform public.ig_retail_manage(jsonb_build_object('action','assign','content_id',w->'content_id','new_client','{"name":"Another fixture brand","contacts":[{"name":"Brand contact","email":"buyer@example.invalid"}]}'::jsonb,'title','New client onboarding','confirmed',true,'terms','Executed brand mandate'));
 assert exists(select from public.ig_clients where name='Another fixture brand' and stage='engaged');
 perform set_config('request.jwt.claims',buyer_claims,true);
 assert exists(select from public.ig_retail_dashboard() where title='New client onboarding' and not room_open);
 assert not ig_private.room_access(shared) and not exists(select from public.ig_retail_dashboard() where room_id=shared);
 assert exists(select from public.ig_retail_dashboard() where title='Brand expansion' and not room_open);
end $$;
rollback;
